return {
    property: "Name", // Default column to search
    operation: "contains", // Default operator
    label: "Name" // Human readable label for the placeholder
}

const displayColumnNames = [
    "Name",
    "Code",
    "Method",
    "Rate",
    // "Frequency",
    // "EffectiveFromDate",
    // "EffectiveToDate",
    "Active",
    "CanCarryForward",
    "AllowEncashment"
];

const displayColumnOptions = {
    valueKey: {
        "Name": "Name",
        "Method": "AccrualMethod",
        "Rate": "AccrualRate",
        "Frequency": "AccrualFrequency"
    },
    type: {
        "Active": "boolean",
        "CanCarryForward": "boolean",
        "AllowEncashment": "boolean",
        "EffectiveFromDate": "date",
        "EffectiveToDate": "date"
    }
};

return {
    columnKeys: displayColumnNames,
    options: displayColumnOptions
};

return [
    // --- Identifiers ---
    {
        label: "ID",
        value: "Id",
        type: "number",
        // operators: ["eq"]
    },
    {
        label: "Code",
        value: "Code",
        type: "string",
        // operators: ["eq", "contains", "startswith"]
    },

    // --- Core Identity ---
    {
        label: "Name",
        value: "Name",
        type: "string",
        // operators: ["contains", "eq", "startswith"]
    },
    {
        label: "Description",
        value: "Description",
        type: "string",
        // operators: ["contains"]
    },
    {
        label: "Active",
        value: "Active",
        type: "boolean",
        operators: ["eq"]
    },

    // --- Accrual Logic ---
    {
        label: "Accrual Method",
        value: "AccrualMethod",
        type: "dropdown",
        source: "accrualMethodMap",
        operators: ["eq"]
    },
    {
        label: "Accrual Frequency",
        value: "AccrualFrequency",
        type: "dropdown",
        source: "frequencyMap",
        operators: ["eq"]
    },
    {
        label: "Accrual Rate",
        value: "AccrualRate",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Accrual Rate Unit",
        value: "AccrualRateUnit",
        type: "dropdown",
        source: "accrualRateUnitMap",
        // operators: ["eq"]
    },

    // --- Limits & Constraints ---
    {
        label: "Max Annual Accrual",
        value: "MaxAnnualAccrual",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Min Annual Accrual",
        value: "MinAnnualAccrual",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Waiting Days",
        value: "WaitingDays",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },

    // --- Carry Forward ---
    {
        label: "Can Carry Forward",
        value: "CanCarryForward",
        type: "boolean",
        operators: ["eq"]
    },
    {
        label: "Carry Forward Limit",
        value: "CarryForwardLimit",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },

    // --- Encashment ---
    {
        label: "Allow Encashment",
        value: "AllowEncashment",
        type: "boolean",
        operators: ["eq"]
    },
    {
        label: "Cash Rate",
        value: "CashRate",
        type: "number",
        // operators: ["eq", "gt", "lt"]
    },
    {
        label: "Cash Frequency",
        value: "CashFrequency",
        type: "dropdown",
        source: "frequencyMap",
        // operators: ["eq"]
    },

    // --- Dates ---
    {
        label: "Effective From",
        value: "EffectiveFromDate",
        type: "date",
        // operators: ["eq", "gt", "lt", "ge", "le"]
    },
    {
        label: "Effective To",
        value: "EffectiveToDate",
        type: "date",
        // operators: ["eq", "gt", "lt", "ge", "le"]
    }
